/* Slides a HUD element in or out from its anchored edge: step T moves by
   D (back while the timer +0x7C runs, forward otherwise), clamped to
   0..23, picks a ramp value from D_L00_0017E4A0 (timer running) or
   D_L00_0017E500, and offsets *Y by it times (height + 52) for flags 1
   (up) / 2 (down), or *X by it times (width + 20) for flags 4 (left) /
   8 (right), rounded (func_001FA888 / func_001FA898 convert). */
void apply_hud_slide_offset(HudElem *e, int *x, int *y, int t, int d) {
    int dx = 0;
    int dy = 0;
    float s;

    if (e->unk7C != 0) {
        t -= d;
    } else {
        t += d;
    }
    if (t < 0) {
        t = 0;
    }
    if (t > 23) {
        t = 23;
    }
    if (e->unk7C != 0) {
        s = hud_slide_ramp_timed[t];
    } else {
        s = hud_slide_ramp_idle[t];
    }
    if (e->flags & 1) {
        dy = -truncate_float_to_s32(s * (IntToFloat(e->h) + 52.0f) + 0.5f);
    } else if (e->flags & 2) {
        dy = truncate_float_to_s32(s * (IntToFloat(e->h) + 52.0f) + 0.5f);
    } else if (e->flags & 4) {
        dx = -truncate_float_to_s32(s * (IntToFloat(e->w) + 20.0f) + 0.5f);
    } else if (e->flags & 8) {
        dx = truncate_float_to_s32(s * (IntToFloat(e->w) + 20.0f) + 0.5f);
    }
    *x += dx;
    *y += dy;
}
/* updates numeric HUD values and dimensions from digit count */
void initialize_numeric_hud_values_and_dimensions(HudElem *e) {
 int *value=e->unk0C;
 int digits;
 int v,flags,width;
 if(value && !((int)value&3)) {
 e->unk78=*value;
 if(e->unk08<e->unk78) e->unk78=e->unk08;
 e->unk74=e->unk78;
 } else { e->unk78=99999; e->unk74=99999; }
 v=e->unk08; digits=0; flags=e->flags; width=e->h;
 while(v>=10) { v/=10; digits++; }
 if(!(flags&3) && (flags&12)) {
 e->h=width+(digits+1)*12;
 if(e->w<14) e->w=14;
 } else {
 if(width<12) e->h=12;
 e->w+=(digits+1)*14;
 }
}
