/* fills 100 hud particle records with randomised positions and drift */
void hud_init_particles(HudElem *e) {
    int i;
    float v, lo, span, hi;
    int n;

    reset_numeric_hud_element(e);
    for (i = 0; i < 100; i++) {
        v = *(float *)&star_init_limit0_gp;
        if (i >= 10) {
            v = *(float *)&star_init_limit1_gp;
            if (i >= 20) v = *(float *)&star_init_limit2_gp;
        }
        n = *(int *)&hud_star_column_count;
        span = (232.0f - (v + v)) / (float)n;
        lo = (v - 116.0f) + (float)(i % n) * span;
        hi = lo + span;
        hud_star_particles[i][0] = random_float_between(v - 17.0f, 17.0f - v);
        hud_star_particles[i][1] = random_float_between(lo, hi);
        hud_star_particles[i][2] = random_float_between(-0.4f, 0.4f);
        hud_star_particles[i][3] = random_float_between(-0.6f, 0.6f);
        hud_star_particles[i][2] += random_float_between(-0.4f, 0.4f);
        hud_star_particles[i][3] += random_float_between(-0.6f, 0.6f);
        hud_star_particles[i][2] += random_float_between(-0.4f, 0.4f);
        hud_star_particles[i][3] += random_float_between(-0.6f, 0.6f);
    }
}
