extern short star_init_limit1_gp;
extern short star_init_limit2_gp;

/* bounces the drifting particles around a box that depends on their index, after updating its
   HUD element (the element it is the callback of, passed on in $a0) */
void hud_update_particles(HudElem *e) {
    int i;
    int cnt;
    int par;
    float *p;

    Hud_UpdateCounter_v(e);
    cnt = rendered_frame_count;
    par = cnt - (cnt / 2) * 2;
    p = hud_star_particles[par];
    for (i = par; i < 100; i += 2) {
        float lim;
        float a, b, na, nb;

        if (i < 10) {
            lim = *(float *)&star_init_limit0_gp;
        } else if (i < 30) {
            lim = *(float *)&star_init_limit1_gp;
        } else {
            lim = *(float *)&star_init_limit2_gp;
        }
        a = lim - 17.0f;
        b = lim - 116.0f;
        na = -a;
        nb = -b;
        p[0] += p[2];
        p[1] += p[3];
        if (p[0] < a) {
            p[0] = a;
            p[2] = -p[2];
        }
        if (na < p[0]) {
            p[0] = na;
            p[2] = -p[2];
        }
        if (p[1] < b) {
            p[1] = b;
            p[3] = -p[3];
        }
        if (nb < p[1]) {
            p[1] = nb;
            p[3] = -p[3];
        }
        p += 8;
    }
}
