// Places a HUD element: looks up its size, offsets x/y by the anchor flags and draws it.
void HudFrame(char *e, int id, int x, int y, int flags, int alpha) {
    if (id >= 0) {
        char *g = texture_group_header;
        char *a = *(char **)(g + 0x20);
        char *b = *(char **)(g + 0x24);
        unsigned char *t;
        int w0, h0, w, h;
        t = (unsigned char *)b + *(short *)(a + id * 4 + 2) * 8;
        x += *(short *)(e + 0x48);
        y += *(short *)(e + 0x4A);
        w0 = 1 << t[6];
        h0 = 1 << t[7];
        w = w0;
        h = h0;
        if (flags & 1) {
            x -= w >> 1;
            y -= h >> 1;
        }
        if (flags & 2) {
            x += w >> 2;
            y += h >> 2;
            w >>= 1;
            h >>= 1;
        }
        if (flags & 4) {
            x -= w0 >> 1;
            y -= h0 >> 1;
            w <<= 1;
            h <<= 1;
        }
        HudSprite(id, x, y, w, h, alpha);
    }
}
